it('compiles static tool schema exactly once during registration and reuses it', async () => {
  const AjvClass = (await import('ajv')).Ajv;
  const compileSpy = jest.spyOn(AjvClass.prototype, 'compile');
  const registry = new ToolRegistry();
  const definition = {
    name: 'counted',
    description: 'Counted compilations',
    inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
  };

  registry.register(definition, async () => 'ok');
  const countAfterRegister = compileSpy.mock.calls.length;

  for (let i = 0; i < 10; i++) {
    await registry.execute('counted', {a: 'val'});
  }

  expect({
    initial: countAfterRegister,
    total: compileSpy.mock.calls.length,
  }).toEqual({
    initial: 1,
    total: 1,
  });

  compileSpy.mockRestore();
});

